sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // Non-blocking Digital Twin Synchronization
    try {
        var machineName = current.getValue("name") || "";
        var machineStatus = current.getValue("status") || "operational";
        var machineCond = current.getValue("machine_condition") || "good";
        var machineLoc = current.getValue("location") || "";

        // Query matching Digital Twin Work Center
        var dtGr = new GlideRecord("x_2056099_indust_0_dt_work_center");
        dtGr.addQuery("work_center_name", machineName);
        dtGr.query();

        if (!dtGr.next()) {
            // Fallback match by facility location if exact name doesn't match
            if (machineLoc) {
                dtGr.initialize();
                dtGr.addQuery("facility_location", machineLoc);
                dtGr.query();
                if (!dtGr.next()) return;
            } else {
                return;
            }
        }

        // Map status
        if (machineStatus === "maintenance" || machineStatus === "offline" || machineStatus === "breakdown") {
            dtGr.setValue("operational_status", "maintenance");
        } else if (machineStatus === "standby") {
            dtGr.setValue("operational_status", "standby");
        } else {
            dtGr.setValue("operational_status", "online");
        }

        // Map Health Index %
        var health = 95;
        if (machineCond === "critical") health = 35;
        else if (machineCond === "poor") health = 60;
        else if (machineCond === "fair") health = 80;
        else health = 95;

        dtGr.setValue("health_index_pct", health);
        dtGr.setValue("calibration_date", new GlideDateTime().getValue());
        dtGr.update();
    } catch (e) {
        // Defensive: never block machine transaction
        gs.warn("Sync Machine Telemetry to Digital Twin non-fatal error: " + e.message);
    }
})(current, previous);
